ee:message.ee:set-payload:
%dw 2.0
output application/json

var firstBussinessError = 
	(error.childErrors map (childError) -> 
		if (childError.errorMessage.payload.error.code?)
			childError.errorMessage.payload.error
		else if (childError.errorMessage.payload.code?)
			childError.errorMessage.payload
		else 
			null
	  filter (err) -> err != null
	  )[0]

---

firstBussinessError default {
  code: 500,
  message: "Internal Server Error",
  description: "An Unexpected error occurs. Please try later",
  dateTime: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"},
  correlationId: vars.correlationId
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json

var requestedItems = vars.originalPayload.items
var fetchedProducts = vars.productsData

---
requestedItems flatMap (item) -> do {
	var product = (fetchedProducts filter ($.productId == item.productId))[0]
	---
	if (product == null)
		[{ productId: item.productId, reason: "PRODUCT_NOT_FOUND" }]
	else if (product.status != "ACTIVE")
		[{ productId: item.productId, reason: "PRODUCT_NOT_ACTIVE" }]
	else if (product.inventory.availableQuantity < item.quantity)
		[{ 
			productId: item.productId, 
			reason: "INSUFFICIENT_STOCK",
			requestedQuantity: item.quantity,
			availableQuantity: product.inventory.availableQuantity
		}]
	else
		[]
}
